#!/usr/bin/env bash
# Package charts/minerva and print a k3s HelmChart manifest that embeds it (spec.chartContent),
# with the given values file. Usage: deploy/k3s-helmchart.sh deploy/uhlix-values.yaml > minerva.yaml
set -euo pipefail
cd "$(dirname "$0")/.."
values=${1:?values file}
tmp=$(mktemp -d); trap 'rm -rf "$tmp"' EXIT
helm package charts/minerva -d "$tmp" >/dev/null
tgz=$(ls "$tmp"/*.tgz)
cat <<YAML
# Generated by minerva/deploy/k3s-helmchart.sh from $(basename "$tgz") and $(basename "$values"). Do not edit by hand.
apiVersion: v1
kind: Namespace
metadata:
  name: minerva
---
apiVersion: helm.cattle.io/v1
kind: HelmChart
metadata:
  name: minerva
  namespace: kube-system
spec:
  targetNamespace: minerva
  failurePolicy: abort
  chartContent: $(base64 -w0 "$tgz")
  valuesContent: |-
$(sed 's/^/    /' "$values")
YAML
